<script setup lang="ts">
import { computed, nextTick, reactive, ref } from 'vue';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { ArrowLeft, Search, SlidersHorizontal, Check, Users, BookOpen, AlertCircle, Upload, Download, History, Settings2, X, ChevronRight, Save } from 'lucide-vue-next';
import RubricAssessment from '../components/RubricAssessment.vue';
import Layout from '../components/Layout.vue'; import Modal from '../components/Modal.vue'; import GradeInput from '../components/GradeInput.vue';
import { api, grade, permission, statusLabel, type Auth } from '../lib';
const props=defineProps<{book:any;history:any[]}>();const book=ref(props.book);const auth=usePage().props.auth as Auth;
const busy=ref(false),message=ref(''),error=ref(''),search=ref(''),onlyPending=ref(false),teamFilter=ref(''),sort=ref('name');
const modal=ref(''),detail=ref<any>(null),rubricKind=ref('team'),allocTeam=ref<any>(null),allocations=reactive<Record<string,string>>({}),draftTeams=ref<any[]>([]),historyData=ref<any>(null),batch=ref({module_id:0,field:'exam',text:''});
const visible=reactive({transversal:true,team:true,defenses:true}); const settings=ref<any>({}); const showColumns=ref(false);
const closed=computed(()=>!(usePage().props.academic as any)?.year?.is_open||['published','finished'].includes(book.value.challenge.status));
const rows=computed(()=>book.value.rows.filter((r:any)=>(!onlyPending.value||r.pending.length)&&(!teamFilter.value||r.team_id===Number(teamFilter.value))&&r.name.toLowerCase().includes(search.value.toLowerCase())).sort((a:any,b:any)=>sort.value==='team'?(a.team_name??'').localeCompare(b.team_name??'')||a.name.localeCompare(b.name):a.name.localeCompare(b.name)));
const complete=computed(()=>book.value.rows.filter((r:any)=>r.pending.length===0).length);
const modules=computed(()=>book.value.modules);
const progressItems=computed(()=>[
  {label:'Transversales', done:book.value.rows.filter((r:any)=>r.transversal!==null).length},
  {label:'Evaluación del equipo', done:book.value.rows.filter((r:any)=>r.team_grade!==null).length},
  ...(book.value.challenge.distribution_enabled?[{label:'Repartos',done:book.value.rows.filter((r:any)=>r.base!==null).length}]:[]),
  {label:'Defensas',done:book.value.rows.filter((r:any)=>!r.pending.some((p:string)=>p.startsWith('Defensa '))).length},
  {label:'Exámenes',done:book.value.rows.filter((r:any)=>!r.pending.some((p:string)=>p.startsWith('Examen '))).length},
  {label:'Notas finales',done:complete.value},
]);
const participatingTeachers=computed(()=>Array.from(new Set<string>(modules.value.flatMap((m:any)=>m.teachers.map((t:any)=>t.name)))).join(' · '));
const writable=(p:string)=>permission(p)&&!closed.value;
const moduleWritable=(p:string,m:any)=>writable(p)&&(auth.role==='admin'||m.teachers.some((t:any)=>t.id===auth.id));
let saveQueue: Promise<boolean> = Promise.resolve(true);
let queued = 0;
function save(payload:any): Promise<boolean> {
  const input = JSON.parse(JSON.stringify(payload));
  queued++; busy.value = true;
  const operation = saveQueue.then(async (previousSucceeded) => {
    if (!previousSucceeded) return false;
    error.value = ''; message.value = 'Guardando…';
    try {
      const data = await api(`/challenges/${book.value.challenge.id}`, {...input, revision:book.value.challenge.revision});
      book.value = data.book;
      return true;
    } catch(e) {
      error.value = (e as Error).message;
      return false;
    }
  });
  saveQueue = operation;
  return operation.finally(() => {
    queued--; busy.value = queued > 0;
    message.value = error.value ? '' : busy.value ? 'Guardando…' : 'Cambios guardados';
    if (!queued) saveQueue = Promise.resolve(true);
  });
}
async function saveGrade(row:any,m:any,field:string,value:string|null|boolean){await save({action:'grades',module_id:m.id,field,entries:[{student_id:row.id,value}]})}
function openAllocation(team:any){allocTeam.value=team;Object.keys(allocations).forEach(k=>delete allocations[k]);team.members.forEach((m:any)=>allocations[m.student_id]=m.allocation??team.grade??'');modal.value='allocation'}
const allocated=computed(()=>Object.values(allocations).reduce((sum,v)=>sum+(Number(v.replace(',','.'))||0),0));
async function submitAllocation(){if(await save({action:'allocation',team_id:allocTeam.value.id,allocations:Object.fromEntries(Object.entries(allocations).map(([k,v])=>[k,v.replace(',','.')]))}))modal.value=''}
function openTeams(){error.value='';draftTeams.value=book.value.teams.map((t:any)=>({name:t.name,students:t.members.map((m:any)=>m.student_id)}));if(!draftTeams.value.length)draftTeams.value=[{name:'Equipo 1',students:[]}];modal.value='teams'}
const teamErrors=computed(()=>draftTeams.value.map((team:any)=>!team.name.trim()?'Escribe un nombre para el equipo.':draftTeams.value.filter((other:any)=>other.name.trim()===team.name.trim()).length>1?'Los nombres de los equipos deben ser distintos.':team.students.length<2||team.students.length>5?'Selecciona entre 2 y 5 estudiantes.':''));
const evaluating=ref(false),evaluationSubject=ref<number|null>(null),evaluationHeading=ref<HTMLElement|null>(null);
function openRubric(kind:string,subjectId?:number){rubricKind.value=kind;evaluationSubject.value=subjectId??subjects.value[0]?.id??null;evaluating.value=true;nextTick(()=>evaluationHeading.value?.focus())}
const currentSubject=computed(()=>subjects.value.find((subject:any)=>subject.id===Number(evaluationSubject.value)));
const evaluationSelections=computed(()=>Object.fromEntries(rubric.value.items.map((item:any)=>[item.key,selected(Number(evaluationSubject.value),item.key)])));
const disabledCriteria=computed(()=>rubricKind.value==='team'?rubric.value.items.filter((item:any)=>item.module_id&&auth.role!=='admin'&&!modules.value.find((module:any)=>module.id===Number(item.module_id))?.teachers.some((teacher:any)=>teacher.id===auth.id)).map((item:any)=>item.key):[]);
function changeSubject(by:number){const index=subjects.value.findIndex((subject:any)=>subject.id===Number(evaluationSubject.value));const target=subjects.value[index+by];if(target)evaluationSubject.value=target.id}
const rubric=computed(()=>rubricKind.value==='team'?book.value.challenge.team_rubric:book.value.challenge.transversal_rubric);
const subjects=computed(()=>rubricKind.value==='team'?book.value.teams:book.value.rows);
function selected(subject:number,key:string){return book.value.assessments.find((a:any)=>a.kind===rubricKind.value&&a.subject_id===subject&&a.criterion===key)?.level}
function openSettings(){settings.value=JSON.parse(JSON.stringify({...book.value.challenge,defenses:Object.fromEntries(modules.value.map((m:any)=>[m.id,m.defense_enabled])),reason:''}));modal.value='settings'}
async function history(){error.value='';try{historyData.value=await api(`/challenges/${book.value.challenge.id}/history`);modal.value='history'}catch(e){error.value=(e as Error).message}}
async function submitBatch(){const entries=batch.value.text.trim().split('\n').filter(Boolean).map((line,i)=>({student_id:rows.value[i]?.id,value:line.trim()===''?null:line.trim().replace(',','.')}));if(entries.length!==rows.value.length){error.value='Introduce una nota por cada estudiante de la lista filtrada, en el mismo orden.';return}if(await save({action:'grades',module_id:batch.value.module_id,field:batch.value.field,entries}))modal.value=''}
function exportCsv(){const data=[['Estudiante','Equipo','Transversales','Reparto','Defensas','Reto final',...modules.value.flatMap((m:any)=>[`Examen ${m.code}`,`Final ${m.code}`])],...rows.value.map((r:any)=>[r.name,r.team_name,r.transversal,r.allocation,r.defenses_total,r.challenge_final,...modules.value.flatMap((m:any)=>[r.modules[m.id].not_enrolled?'No matriculado':r.modules[m.id].exam,r.modules[m.id].not_enrolled?'No matriculado':r.modules[m.id].final])])];const escape=(v:any)=>{let s=String(v??'Pendiente');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const blob=new Blob(['\ufeff'+data.map(row=>row.map(escape).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='erronk2d-reto.csv';a.click();URL.revokeObjectURL(a.href)}
const defenseDetail=ref<any>({});function openDefense(row:any,m:any){defenseDetail.value={student_id:row.id,name:row.name,module:m,not_enrolled:row.modules[m.id].not_enrolled,value:row.modules[m.id].defense??'',date:row.modules[m.id].defense_date??new Date().toISOString().slice(0,10),notes:row.modules[m.id].defense_notes??''};modal.value='defense'}
async function submitDefense(){const d=defenseDetail.value;if(await save({action:'grades',field:'defense',module_id:d.module.id,entries:[{student_id:d.student_id,value:d.value===''?null:String(d.value).replace(',','.'),date:d.date,notes:d.notes}]}))modal.value=''}
</script>
<template><Layout><Head :title="book.challenge.name"/>
<div class="topline"><Link href="/" class="back-link"><ArrowLeft :size="16"/>Todos los retos</Link><span>{{book.year}} / {{book.classroom}} / {{book.period}}</span></div>
<header class="page-heading compact"><div><div class="eyebrow">{{book.classroom}} <span class="badge" :class="book.challenge.status">{{statusLabel[book.challenge.status]}}</span></div><h1>{{book.challenge.name}}</h1><p class="muted">{{book.description||book.challenge.description||'Una visión completa del aprendizaje de tu grupo.'}}</p></div><div class="actions"><button class="button" @click="history"><History :size="17"/>Histórico</button><button v-if="permission('manage_challenges')" class="icon-button bordered" title="Configurar reto" aria-label="Configurar reto" @click="openSettings"><Settings2 :size="19"/></button><button v-if="permission('publish_results')&&!closed" class="button primary" @click="modal='publish'"><Upload :size="17"/>Publicar</button><button v-if="permission('publish_results')&&closed" class="button" @click="settings={reason:''};modal='reopen'">Reabrir</button></div></header>
<template v-if="!evaluating">
<section class="challenge-summary"><div><Users :size="20"/><strong>{{book.rows.length}}</strong><span>estudiantes</span></div><div><strong>{{book.teams.length}}</strong><span>equipos</span><button v-if="writable('manage_teams')" @click="openTeams">Gestionar</button></div><div><BookOpen :size="20"/><strong>{{modules.length}}</strong><span>módulos</span></div><div class="progress-summary"><span><strong>{{complete}} / {{book.rows.length}}</strong> evaluaciones completas</span><div class="progress-track"><i :style="{width:`${book.rows.length?complete/book.rows.length*100:0}%`}"/></div></div></section>
<section class="evaluation-progress" aria-label="Progreso por tipo de evaluación"><div v-for="item in progressItems" :key="item.label"><span>{{item.label}}</span><strong :class="{'low-grade':item.done<book.rows.length}">{{item.done}} / {{book.rows.length}}</strong><small>{{book.rows.length-item.done}} pendientes</small></div></section>
<p class="helper">Profesorado participante: {{participatingTeachers||'Sin asignar'}}</p>
<div v-if="book.issues.length" class="notice warning"><AlertCircle :size="18"/><div v-for="issue in book.issues">{{issue}}</div></div>
<div class="workspace-heading"><div><h2>Matriz de evaluación <span class="live-dot"/></h2><p>Una única nota de reto. Todos los módulos conectados.</p></div><div class="save-status" aria-live="polite"><Check v-if="message==='Cambios guardados'" :size="15"/>{{message}}</div></div>
<div v-if="error" class="notice error" role="alert">{{error}}<button @click="router.reload()">Actualizar datos</button></div>
<div class="matrix-toolbar"><div class="search-box"><Search :size="16"/><input v-model="search" aria-label="Buscar estudiante" placeholder="Buscar estudiante…"/></div><select v-model="teamFilter" aria-label="Filtrar equipo"><option value="">Todos los equipos</option><option v-for="t in book.teams" :value="t.id">{{t.name}}</option></select><select v-model="sort" aria-label="Ordenar estudiantes"><option value="name">Nombre A–Z</option><option value="team">Por equipo</option></select><label class="check"><input type="checkbox" v-model="onlyPending"/>Solo pendientes</label><div class="toolbar-spacer"/><button class="icon-button" aria-label="Mostrar u ocultar columnas" @click="showColumns=!showColumns"><SlidersHorizontal :size="18"/></button><button class="icon-button" aria-label="Exportar matriz CSV" @click="exportCsv"><Download :size="18"/></button></div>
<div v-if="showColumns" class="column-options"><label class="check"><input type="checkbox" v-model="visible.transversal"/>Transversales</label><label class="check"><input type="checkbox" v-model="visible.team"/>Nota de equipo y reparto</label><label class="check"><input type="checkbox" v-model="visible.defenses"/>Defensas por módulo</label></div>
<div class="table-scroll matrix-scroll"><table class="matrix"><thead><tr><th class="frozen student-col" rowspan="2">ESTUDIANTE <small>Equipo / estado</small></th><th v-if="visible.transversal" class="group-trans" rowspan="2">TRANSVERSALES <small>{{book.challenge.component_weights.transversal}}%</small></th><th v-if="visible.team" :colspan="book.challenge.distribution_enabled?2:1" class="group-team">VALORACIÓN DEL EQUIPO</th><th colspan="2" class="group-challenge">NOTA COMÚN A TODOS LOS MÓDULOS</th><th v-for="m in modules" :colspan="visible.defenses&&m.defense_enabled?3:2" class="group-module">{{m.code}}</th><th rowspan="2">ESTADO</th></tr><tr><th v-if="visible.team">Equipo</th><th v-if="visible.team&&book.challenge.distribution_enabled">Reparto</th><th class="defense-total">Σ Defensas</th><th class="challenge-total">Reto final <small>{{book.challenge.component_weights.challenge}}%</small></th><template v-for="m in modules"><th v-if="visible.defenses&&m.defense_enabled">Defensa</th><th>Examen <small>{{book.challenge.component_weights.exam}}%</small></th><th class="module-final">Final</th></template></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td class="frozen student-col"><button class="student-button" @click="detail=row;modal='detail'"><span class="student-avatar">{{row.name.split(' ').slice(0,2).map((n:string)=>n[0]).join('')}}</span><span><strong>{{row.name}}</strong><small>{{row.team_name??'Sin equipo'}}</small></span></button></td><td v-if="visible.transversal"><button class="grade-link" @click="detail=row;modal='detail'">{{grade(row.transversal)}}</button></td><td v-if="visible.team"><button class="grade-link" @click="openRubric('team',row.team_id)">{{grade(row.team_grade)}}</button></td><td v-if="visible.team&&book.challenge.distribution_enabled"><button class="allocation-cell" :disabled="!row.team_id" @click="openAllocation(book.teams.find((t:any)=>t.id===row.team_id))">{{grade(row.allocation)}}<span v-if="row.pending.includes('Reparto pendiente o inválido')" class="pending-dot"/></button></td><td class="defense-total"><button class="grade-link" @click="detail=row;modal='detail'">{{grade(row.defenses_total)}}</button></td><td class="challenge-total"><button class="grade-link bold" @click="detail=row;modal='detail'">{{grade(row.challenge_final)}}</button></td><template v-for="m in modules"><td v-if="visible.defenses&&m.defense_enabled"><button class="defense-cell" :class="{editable:moduleWritable('enter_defenses',m)}" @click="openDefense(row,m)">{{grade(row.modules[m.id].defense)}}</button></td><td><GradeInput :model-value="row.modules[m.id].exam" :label="`Examen ${m.code} de ${row.name}`" :disabled="row.modules[m.id].not_enrolled||!moduleWritable('enter_exams',m)" @save="saveGrade(row,m,'exam',$event)"/></td><td class="module-final"><button class="grade-link bold" :class="{'low-grade':row.modules[m.id].final!==null&&Number(row.modules[m.id].final)<5}" @click="detail=row;modal='detail'">{{row.modules[m.id].not_enrolled?'NM':grade(row.modules[m.id].final)}}</button></td></template><td><span v-if="!row.pending.length" class="row-state done"><Check :size="14"/>Listo</span><button v-else class="row-state pending" @click="detail=row;modal='detail'">{{row.pending.length}} pendientes</button></td></tr><tr v-if="!rows.length"><td colspan="30" class="empty-cell">No hay estudiantes que coincidan con estos filtros.</td></tr></tbody></table></div>
<div class="matrix-footer"><span>{{rows.length}} estudiantes · <kbd>Tab</kbd> siguiente campo · <kbd>Enter</kbd> guardar · <kbd>Esc</kbd> cancelar edición</span><span>— Pendiente de evaluar</span></div>
<div class="bottom-actions"><button class="button" @click="openRubric('team')">Rúbrica del equipo <ChevronRight :size="16"/></button><button class="button" @click="openRubric('teacher')">Transversales del profesorado <ChevronRight :size="16"/></button><button v-if="writable('enter_exams')||writable('enter_defenses')" class="button" @click="batch={module_id:modules.find((m:any)=>moduleWritable('enter_exams',m)||moduleWritable('enter_defenses',m))?.id??0,field:'exam',text:''};modal='batch'">Introducción masiva</button><select v-if="writable('manage_challenges')" :value="book.challenge.status" aria-label="Estado del reto" :disabled="busy" @change="save({action:'status',status:($event.target as HTMLSelectElement).value})"><option value="draft">Borrador</option><option value="active">En curso</option><option value="evaluating">En evaluación</option><option value="finished">Finalizado</option></select></div>
<p class="formula-note">{{book.challenge.distribution_enabled?'Reparto individual':'Nota del equipo'}} + todas las defensas = <strong>una única nota final del reto</strong>. La misma nota participa en todos los módulos.</p>
</template>
<section v-else class="rubric-evaluation">
  <div class="rubric-evaluation-header"><div><button class="back-link" :disabled="busy" @click="evaluating=false"><ArrowLeft :size="16"/>Volver a la matriz de notas</button><h2 ref="evaluationHeading" tabindex="-1">{{rubricKind==='team'?'Rúbrica del equipo':'Transversales del profesorado'}}</h2></div><span class="save-status" role="status">{{message}}</span></div>
  <div v-if="error" class="notice error" role="alert">{{error}}<button @click="router.reload()">Actualizar datos</button></div>
  <p v-if="closed" class="notice info">Solo lectura. El reto o el curso académico está cerrado.</p>
  <div class="rubric-evaluation-header"><label>{{rubricKind==='team'?'Equipo a evaluar':'Estudiante a evaluar'}}<select v-model="evaluationSubject" :disabled="busy"><option v-for="subject in subjects" :key="subject.id" :value="subject.id">{{subject.name}}</option></select></label><div class="actions"><button class="button" :disabled="busy||!currentSubject||currentSubject.id===subjects[0]?.id" @click="changeSubject(-1)">Anterior</button><button class="button" :disabled="busy||!currentSubject||currentSubject.id===subjects[subjects.length-1]?.id" @click="changeSubject(1)">Siguiente</button></div></div>
  <RubricAssessment v-if="currentSubject" :rubric="rubric" :subject="currentSubject.name" :selections="evaluationSelections" :show-modules="rubricKind==='team'" :modules="modules" :disabled="busy||!writable(rubricKind==='team'?'evaluate_team':'evaluate_transversal')" :disabled-criteria="disabledCriteria" @select="(key,level)=>save({action:'assess',kind:rubricKind,entries:[{subject_id:Number(evaluationSubject),criterion:key,level}]})"/>
  <p v-else class="empty-state">{{rubricKind==='team'?'Crea los equipos del reto para poder evaluarlos.':'No hay estudiantes en este reto.'}}</p>
</section>

<Modal v-if="modal==='detail'" :title="detail.name" @close="modal=''" wide><div class="detail-grid"><section><p class="eyebrow">COMPETENCIAS TRANSVERSALES</p><div class="breakdown-row"><span>Autoevaluación · {{book.challenge.transversal_weights.self}}%</span><strong>{{grade(detail.self)}}</strong></div><div class="breakdown-row"><span>Compañeros · {{book.challenge.transversal_weights.peer}}%</span><strong>{{grade(detail.peer)}}</strong></div><div class="breakdown-row"><span>Profesorado · {{book.challenge.transversal_weights.teacher}}%</span><strong>{{grade(detail.teacher)}}</strong></div><div class="breakdown-row total"><span>Transversales</span><strong>{{grade(detail.transversal)}}</strong></div></section><section><p class="eyebrow">NOTA FINAL DEL RETO</p><div class="breakdown-row"><span>Nota del equipo</span><strong>{{grade(detail.team_grade,4)}}</strong></div><div class="breakdown-row"><span>{{book.challenge.distribution_enabled?'Reparto':'Base sin reparto'}}</span><strong>{{grade(detail.base,4)}}</strong></div><div v-for="m in modules.filter((m:any)=>m.defense_enabled)" class="breakdown-row"><span>Defensa {{m.code}}</span><strong>{{grade(detail.modules[m.id].defense,4)}}</strong></div><div class="breakdown-row"><span>Resultado antes de límites</span><strong>{{grade(detail.challenge_raw,4)}}</strong></div><div class="breakdown-row total"><span>Única nota final del reto</span><strong>{{grade(detail.challenge_final,4)}}</strong></div></section></div><div class="module-breakdowns"><section v-for="m in modules"><h3>{{m.code}}</h3><label class="check"><input type="checkbox" :checked="detail.modules[m.id].not_enrolled" :disabled="busy||!moduleWritable('enter_exams',m)" @change="saveGrade(detail,m,'not_enrolled',($event.target as HTMLInputElement).checked).then(()=>detail=book.rows.find((r:any)=>r.id===detail.id))"/>No matriculado</label><p>{{grade(detail.transversal)}} × {{book.challenge.component_weights.transversal}}% + {{grade(detail.challenge_final)}} × {{book.challenge.component_weights.challenge}}% + {{grade(detail.modules[m.id].exam)}} × {{book.challenge.component_weights.exam}}%</p><strong>{{detail.modules[m.id].not_enrolled?'No matriculado':grade(detail.modules[m.id].final)}}</strong></section></div><div v-if="detail.pending.length" class="notice warning">Pendiente: {{detail.pending.join(' · ')}}</div><p class="helper">Los cálculos conservan la precisión interna; las notas mostradas están redondeadas.</p></Modal>
<Modal v-if="modal==='allocation'" :title="`Reparto · ${allocTeam.name}`" @close="modal=''"><div class="points-banner"><div><small>NOTA DEL EQUIPO</small><strong>{{grade(allocTeam.grade,4)}}</strong></div><span>× {{allocTeam.members.length}} =</span><div><small>PUNTOS A REPARTIR</small><strong>{{grade(allocTeam.points,4)}}</strong></div></div><form @submit.prevent="submitAllocation"><label v-for="member in allocTeam.members" class="allocation-row"><span>{{book.rows.find((r:any)=>r.id===member.student_id)?.name}}</span><input v-model="allocations[member.student_id]" inputmode="decimal" required :disabled="!writable('evaluate_team')"/></label><div class="breakdown-row total"><span>Total introducido</span><strong>{{grade(allocated,4)}}</strong></div><p class="helper">El profesor registra el reparto acordado presencialmente. Se validará la suma exacta antes de guardar.</p><p v-if="error" class="notice error" role="alert">{{error}}</p><button v-if="writable('evaluate_team')" class="button primary full" :disabled="busy||allocTeam.grade===null">Guardar reparto</button></form></Modal>
<Modal v-if="modal==='teams'" title="Organizar equipos" @close="modal=''" wide><p class="helper">Entre 2 y 5 estudiantes por equipo. La composición se conserva cuando empiezan las evaluaciones.</p><div v-if="!book.rows.length" class="notice"><p>Este reto no tiene estudiantes. Asígnalos primero a su grupo desde <Link :href="(usePage().props.setupNavigation as any[]).find(link=>link.section==='students')?.url">Organización → Estudiante</Link>.</p><p>Después puedes incorporar la matrícula actual a este reto vacío. Los retos con evaluaciones conservan sus participantes.</p><button class="button" :disabled="busy" @click="save({action:'participants'})">Incorporar estudiantes del grupo</button></div><div class="team-editor"><section v-for="(team,index) in draftTeams"><div class="actions"><input v-model="team.name" aria-label="Nombre de equipo"/><button class="icon-button" aria-label="Quitar equipo" @click="draftTeams.splice(index,1)"><X :size="18"/></button></div><label v-for="row in book.rows" class="check"><input type="checkbox" v-model="team.students" :value="row.id" :disabled="!team.students.includes(row.id)&&draftTeams.some((t:any)=>t.students.includes(row.id))"/>{{row.name}}</label><small>{{team.students.length}} integrantes</small><p v-if="teamErrors[index]" class="notice error" role="alert">{{teamErrors[index]}}</p></section></div><div class="actions"><button class="button" @click="draftTeams.push({name:`Equipo ${draftTeams.length+1}`,students:[]})">Añadir equipo</button><button class="button primary" :disabled="busy||!draftTeams.length||teamErrors.some(Boolean)||!book.rows.length" @click="save({action:'teams',teams:draftTeams}).then(ok=>{if(ok)modal=''})">Guardar equipos</button></div><p v-if="error" class="notice error">{{error}}</p></Modal>
<Modal v-if="modal==='settings'" title="Configuración del reto" @close="modal=''" wide><form @submit.prevent="save({action:'configure',...settings}).then(ok=>{if(ok)modal=''})" class="form-grid"><label class="span-2">Nombre<input v-model="settings.name" required/></label><label class="span-2">Descripción<textarea v-model="settings.description"/></label><label>Inicio<input type="date" v-model="settings.starts_at"/></label><label>Fin<input type="date" v-model="settings.ends_at"/></label><label>Peso en la Evaluación<input v-model="settings.weight" required inputmode="decimal"/></label><label class="check"><input v-model="settings.distribution_enabled" type="checkbox"/>Reparto individual</label><label class="check span-2"><input v-model="settings.clamp_grade" type="checkbox"/>Limitar nota final del reto a 0–10</label><fieldset><legend>Nota de módulo · suma 100%</legend><label v-for="(label,key) in {transversal:'Transversales',challenge:'Reto',exam:'Examen'}">{{label}}<input v-model="settings.component_weights[key]" inputmode="decimal"/></label></fieldset><fieldset><legend>Transversales · suma 100%</legend><label v-for="(label,key) in {self:'Autoevaluación',peer:'Compañeros',teacher:'Profesorado'}">{{label}}<input v-model="settings.transversal_weights[key]" inputmode="decimal"/></label></fieldset><fieldset class="span-2"><legend>Defensas por módulo</legend><label v-for="m in modules" class="check"><input v-model="settings.defenses[m.id]" type="checkbox"/>{{m.code}}</label></fieldset><label class="span-2">Observaciones<textarea v-model="settings.notes"/></label><label class="span-2">Motivo de la corrección, si ha estado publicado<input v-model="settings.reason"/></label><p v-if="error" class="notice error span-2">{{error}}</p><button class="button primary span-2" :disabled="busy||closed">Guardar configuración</button></form></Modal>
<Modal v-if="modal==='publish'" title="Publicar resultados" @close="modal=''"><p>Se conservará una versión de las notas y el alumnado podrá consultar su desglose. El reto quedará cerrado a modificaciones.</p><p v-if="!book.complete" class="notice warning">Hay datos pendientes o errores. Completa el reto antes de publicar.</p><p v-if="error" class="notice error">{{error}}</p><button class="button primary full" :disabled="busy||!book.complete" @click="save({action:'publish'}).then(ok=>{if(ok)modal=''})">Publicar resultados</button></Modal>
<Modal v-if="modal==='reopen'" title="Reabrir para corregir" @close="modal=''"><form @submit.prevent="save({action:'reopen',reason:settings.reason}).then(ok=>{if(ok)modal=''})"><p>Se conserva la publicación anterior. Las notas volverán a estar disponibles para el alumnado cuando publiques la corrección.</p><label>Motivo de la corrección<textarea v-model="settings.reason" required minlength="5"/></label><p v-if="error" class="notice error">{{error}}</p><button class="button primary full" :disabled="busy">Reabrir reto</button></form></Modal>
<Modal v-if="modal==='history'" title="Histórico del reto" @close="modal=''" wide><h3>Publicaciones conservadas</h3><details v-for="p in historyData.publications"><summary>Versión {{p.version}} · {{new Date(p.created_at).toLocaleString('es-ES')}}</summary><table><thead><tr><th>Estudiante</th><th>Reto final</th><th>Módulos</th></tr></thead><tbody><tr v-for="r in p.snapshot.rows"><td>{{r.name}}</td><td>{{grade(r.challenge_final)}}</td><td>{{p.snapshot.modules.map((m:any)=>`${m.code}: ${r.modules[m.id].not_enrolled?'No matriculado':grade(r.modules[m.id].final)}`).join(' · ')}}</td></tr></tbody></table></details><p v-if="!historyData.publications.length" class="muted">Todavía no hay publicaciones.</p><h3>Últimos cambios</h3><div v-for="e in historyData.events" class="audit-row"><span>{{e.action}}</span><small>Usuario {{e.user_id}} · {{new Date(e.created_at).toLocaleString('es-ES')}}</small><p v-if="e.reason">{{e.reason}}</p></div></Modal>
<Modal v-if="modal==='batch'" title="Introducir varias notas" @close="modal=''"><form @submit.prevent="submitBatch"><div class="form-grid"><label>Módulo<select v-model="batch.module_id"><option v-for="m in modules.filter((m:any)=>moduleWritable('enter_exams',m)||moduleWritable('enter_defenses',m))" :value="m.id">{{m.code}}</option></select></label><label>Tipo<select v-model="batch.field"><option value="exam">Examen</option><option value="defense">Defensa</option></select></label></div><p class="helper">Pega una nota por línea, siguiendo este orden de {{rows.length}} estudiantes. El lote se guarda completo o se rechaza entero.</p><div class="batch-grid"><ol><li v-for="r in rows">{{r.name}}</li></ol><textarea v-model="batch.text" :rows="Math.min(rows.length,20)" required aria-label="Notas, una por línea" placeholder="7,5&#10;8&#10;6,25"/></div><p v-if="error" class="notice error">{{error}}</p><button class="button primary full" :disabled="busy">Guardar todas las notas</button></form></Modal>
<Modal v-if="modal==='defense'" :title="`Defensa ${defenseDetail.module.code} · ${defenseDetail.name}`" @close="modal=''"><form @submit.prevent="submitDefense"><label>Puntos que suma o resta<input v-model="defenseDetail.value" inputmode="decimal" placeholder="Por ejemplo, +0,5 o -0,25" :disabled="defenseDetail.not_enrolled||!moduleWritable('enter_defenses',defenseDetail.module)"/></label><label>Fecha<input v-model="defenseDetail.date" type="date" :disabled="defenseDetail.not_enrolled||!moduleWritable('enter_defenses',defenseDetail.module)"/></label><label>Observaciones<textarea v-model="defenseDetail.notes" :disabled="defenseDetail.not_enrolled||!moduleWritable('enter_defenses',defenseDetail.module)"/></label><p class="helper">Cero significa defensa realizada sin ajuste. Un campo vacío indica que está pendiente.</p><p v-if="error" class="notice error">{{error}}</p><button v-if="!defenseDetail.not_enrolled&&moduleWritable('enter_defenses',defenseDetail.module)" class="button primary full" :disabled="busy">Guardar defensa</button></form></Modal>
</Layout></template>
